#include "gymServer.hpp"

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <cstring>
#include <iostream>

GymServer &GymServer::instance() {
    static GymServer inst;
    return inst;
}

GymServer::~GymServer() {
    stop();
}

void GymServer::start(int port) {
    if (running.exchange(true)) return;  // already started
    worker = std::thread(&GymServer::serverLoop, this, port);
}

void GymServer::stop() {
    if (!running.exchange(false)) return;
    // Closing the sockets unblocks accept()/recv() in the worker thread.
    if (clientFd >= 0) ::shutdown(clientFd, SHUT_RDWR);
    if (serverFd >= 0) ::shutdown(serverFd, SHUT_RDWR);
    if (worker.joinable()) worker.join();
    closeClient();
    if (serverFd >= 0) { ::close(serverFd); serverFd = -1; }
}

void GymServer::closeClient() {
    connected.store(false);
    if (clientFd >= 0) { ::close(clientFd); clientFd = -1; }
}

void GymServer::serverLoop(int port) {
    serverFd = ::socket(AF_INET, SOCK_STREAM, 0);
    if (serverFd < 0) {
        std::cerr << "[GymServer] socket() failed: " << std::strerror(errno) << "\n";
        running.store(false);
        return;
    }

    int opt = 1;
    ::setsockopt(serverFd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    sockaddr_in addr;
    std::memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(static_cast<uint16_t>(port));

    if (::bind(serverFd, reinterpret_cast<sockaddr *>(&addr), sizeof(addr)) < 0) {
        std::cerr << "[GymServer] bind(" << port << ") failed: "
                  << std::strerror(errno) << "\n";
        running.store(false);
        return;
    }
    if (::listen(serverFd, 1) < 0) {
        std::cerr << "[GymServer] listen() failed: " << std::strerror(errno) << "\n";
        running.store(false);
        return;
    }

    std::cerr << "[GymServer] listening on port " << port << "\n";

    while (running.load()) {
        int fd = ::accept(serverFd, nullptr, nullptr);
        if (fd < 0) {
            if (!running.load()) break;
            continue;  // transient error, retry
        }
        clientFd = fd;
        rxBuffer.clear();
        connected.store(true);
        std::cerr << "[GymServer] client connected\n";

        // Read loop: split the byte stream into '\n'-terminated lines.
        char buf[4096];
        while (running.load()) {
            ssize_t n = ::recv(clientFd, buf, sizeof(buf), 0);
            if (n <= 0) break;  // disconnect or error
            rxBuffer.append(buf, static_cast<size_t>(n));
            size_t pos;
            while ((pos = rxBuffer.find('\n')) != std::string::npos) {
                std::string line = rxBuffer.substr(0, pos);
                rxBuffer.erase(0, pos + 1);
                std::lock_guard<std::mutex> lk(inMutex);
                inQueue.push(std::move(line));
            }
        }

        std::cerr << "[GymServer] client disconnected\n";
        closeClient();
    }
}

bool GymServer::pollLine(std::string &out) {
    std::lock_guard<std::mutex> lk(inMutex);
    if (inQueue.empty()) return false;
    out = std::move(inQueue.front());
    inQueue.pop();
    return true;
}

bool GymServer::sendLine(const std::string &line) {
    std::lock_guard<std::mutex> lk(sendMutex);
    if (clientFd < 0) return false;
    std::string payload = line;
    payload.push_back('\n');
    size_t sent = 0;
    while (sent < payload.size()) {
        ssize_t n = ::send(clientFd, payload.data() + sent,
                           payload.size() - sent, 0);
        if (n <= 0) return false;
        sent += static_cast<size_t>(n);
    }
    return true;
}
